#!/usr/bin/env bash
set -euo pipefail

# Generated by RoleCraft — https://rolecraft.omhinge.cloud
# Creates an IAM role with its trust policy and permissions.

ROLE_NAME='lambda-api'

# Trust policy: who can assume the role
cat > trust.json <<'ROLECRAFT_EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "lambda.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
ROLECRAFT_EOF

# Permissions policy
cat > policy.json <<'ROLECRAFT_EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "LambdaInvokeFunction",
      "Effect": "Allow",
      "Action": "lambda:InvokeFunction",
      "Resource": [
        "arn:aws:lambda:*:*:function:orders-api",
        "arn:aws:lambda:*:*:function:orders-api:*"
      ]
    },
    {
      "Sid": "DynamodbReadWriteTable",
      "Effect": "Allow",
      "Action": [
        "dynamodb:BatchGetItem",
        "dynamodb:BatchWriteItem",
        "dynamodb:ConditionCheckItem",
        "dynamodb:DeleteItem",
        "dynamodb:DescribeTable",
        "dynamodb:GetItem",
        "dynamodb:PutItem",
        "dynamodb:Query",
        "dynamodb:Scan",
        "dynamodb:UpdateItem"
      ],
      "Resource": "arn:aws:dynamodb:*:*:table/orders"
    },
    {
      "Sid": "DynamodbReadWriteIndex",
      "Effect": "Allow",
      "Action": [
        "dynamodb:Query",
        "dynamodb:Scan"
      ],
      "Resource": "arn:aws:dynamodb:*:*:table/orders/index/*"
    },
    {
      "Sid": "LogsWriteGroup",
      "Effect": "Allow",
      "Action": [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ],
      "Resource": "arn:aws:logs:*:*:log-group:/aws/lambda/orders-api:*"
    }
  ]
}
ROLECRAFT_EOF

aws iam create-role --role-name "$ROLE_NAME" --assume-role-policy-document file://trust.json --description 'Created with RoleCraft'
aws iam put-role-policy --role-name "$ROLE_NAME" --policy-name "${ROLE_NAME}-inline" --policy-document file://policy.json

echo "Created role $ROLE_NAME."
echo "Added inline policy ${ROLE_NAME}-inline."
